/**
 * 1. FormItem网格布局
 * 2. 居中，居右，居左布局
 * 3. 行内布局
 * 4. 吸底布局
 */
import React, { useRef, useLayoutEffect, useState } from 'react';
import { Space, SpaceProps } from '@arco-design/web-react';
import { BaseItem } from '../FormItem';
import { usePrefixCls } from '../__builtins__';
import StickyBox from 'react-sticky-box';
import cls from 'classnames';
import { IFormItemProps } from '../FormItem/interface';

interface IStickyProps extends React.ComponentProps<typeof StickyBox> {
  align?: React.CSSProperties['textAlign'];
}

type IFormButtonGroupProps = Omit<SpaceProps, 'align' | 'size'> & {
  align?: React.CSSProperties['textAlign'];
  gutter?: number;
};

type ComposedButtonGroup = React.FC<IFormButtonGroupProps> & {
  Sticky: React.FC<React.PropsWithChildren<IStickyProps>>;
  FormItem: React.FC<
    IFormItemProps & {
      gutter?: number;
    }
  >;
};

function getDefaultBackground() {
  // have to add to the document in order to use getComputedStyle
  const div = document.createElement('div');
  document.head.appendChild(div);
  const bg = window.getComputedStyle(div).backgroundColor;
  document.head.removeChild(div);
  return bg;
}

function getInheritedBackgroundColor(el: HTMLElement): string {
  // get default style for current browser
  const defaultStyle = getDefaultBackground(); // typically "rgba(0, 0, 0, 0)"

  // get computed color for el
  const { backgroundColor } = window.getComputedStyle(el);

  // if we got a real value, return it
  // eslint-disable-next-line eqeqeq
  if (backgroundColor != defaultStyle) {
    return backgroundColor;
  }

  // if we've reached the top parent el without getting an explicit color, return default
  if (!el.parentElement) {
    return defaultStyle;
  }

  // otherwise, recurse and try again on parent element
  return getInheritedBackgroundColor(el.parentElement);
}

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
export const FormButtonGroup: ComposedButtonGroup = ({ align, gutter, ...props }) => {
  const prefixCls = usePrefixCls('formily-button-group');
  return (
    <Space
      {...props}
      size={gutter}
      className={cls(prefixCls, props.className)}
      style={{
        ...props.style,
        justifyContent: align === 'left' ? 'flex-start' : align === 'right' ? 'flex-end' : 'center',
        display: 'flex',
      }}
    >
      {props.children}
    </Space>
  );
};

FormButtonGroup.defaultProps = {
  align: 'left',
};

const FormItem: ComposedButtonGroup['FormItem'] = ({ gutter, ...props }) => (
  <BaseItem
    {...props}
    label=" "
    style={{
      margin: 0,
      padding: 0,
      ...props.style,
      width: '100%',
    }}
    colon={false}
  >
    {props.children ? <Space size={gutter}>{props.children}</Space> : props.children}
  </BaseItem>
);

FormButtonGroup.FormItem = FormItem;

const Sticky: React.FC<React.PropsWithChildren<IStickyProps>> = ({ align, ...props }) => {
  const ref = useRef(null);
  const [color, setColor] = useState('transparent');
  const prefixCls = usePrefixCls('formily-button-group');

  useLayoutEffect(() => {
    if (ref.current) {
      const computed = getInheritedBackgroundColor(ref.current);
      if (computed !== color) {
        setColor(computed);
      }
    }
  });
  return (
    <StickyBox
      {...props}
      className={cls(`${prefixCls}-sticky`, props.className)}
      style={{
        backgroundColor: color,
        ...props.style,
      }}
      bottom
    >
      <div
        ref={ref}
        className={`${prefixCls}-sticky-inner`}
        style={{
          ...props.style,
          justifyContent: align === 'left' ? 'flex-start' : align === 'right' ? 'flex-end' : 'center',
        }}
      >
        {props.children}
      </div>
    </StickyBox>
  );
};

FormButtonGroup.Sticky = Sticky;

FormButtonGroup.Sticky.defaultProps = {
  align: 'left',
};

export default FormButtonGroup;
